using System;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class BeachBallChecks {
 [MenuItem("BWVR/Verify creature favorites")]
 public static void Interests(){var memory=new HybridState();var a=new CreatureCandidate{action=CreatureAction.PlayWithToy,target="ball",need=.5f};var b=new CreatureCandidate{action=CreatureAction.PlayWithToy,target="rattle",need=.5f};int Count(float interest){a.interest=interest;return Enumerable.Range(0,500).Count(i=>CreatureDecisionModel.Select(new[]{a,b},1347,i)==a);}int neutral=Count(0);for(int i=0;i<8;i++)memory.Experience("ball",.06f);int favorite=Count((memory.Interest("ball").appeal-.5f)*.9f);for(int i=0;i<9;i++)memory.Experience("ball",-.1f);int avoided=Count((memory.Interest("ball").appeal-.5f)*.9f);if(favorite<=neutral+100||avoided>=neutral-100)throw new Exception("Object preference has no measurable choice effect");var saved=JsonUtility.FromJson<HybridState>(JsonUtility.ToJson(memory));if(!saved.Valid()||saved.interests.Length!=1)throw new Exception("Favorites do not save");saved.interests[0].appeal=float.NaN;if(saved.Valid())throw new Exception("Invalid favorite accepted");Debug.Log($"BWVR_INTEREST_PASS: object choices neutral={neutral}, favorite={favorite}, avoided={avoided}; bounded target memory and save validation");}
 [MenuItem("BWVR/Verify physical beachball and consequences (Play mode)")]
 public static void Verify(){if(!EditorApplication.isPlaying)throw new Exception("Enter Play mode first");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=UnityEngine.Object.FindAnyObjectByType<CreatureHybrid>();var ball=UnityEngine.Object.FindAnyObjectByType<BeachBall>();var nav=god.GetComponent<IslandNavigator>();var mind=god.GetComponent<CreatureCuriosity>();var field=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)field.GetValue(slice);god.Interrupt("Ball QA");var test=new SliceState{water=100,developmentFocus=true};field.SetValue(slice,test);var residents=slice.GetComponentsInChildren<VillagerSocial>();var residentPositions=residents.Select(v=>v.transform.position).ToArray();var godPosition=god.transform.position;
  void Hit(PlayImpactTarget target,bool byCreature=true){var struck=(HashSet<string>)typeof(BeachBall).GetField("struck",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(ball);for(int approach=0;approach<8;approach++){ball.ReturnHome();var bounds=target.Bounds(nav.world.Scale);var direction=Quaternion.Euler(0,approach*45,0)*Vector3.right;float extent=Mathf.Abs(direction.x)*bounds.extents.x+Mathf.Abs(direction.z)*bounds.extents.z;ball.transform.position=bounds.center-direction*(extent+(ball.Radius+2)*nav.world.Scale);ball.Throw(direction,byCreature,24);ball.Body.linearVelocity=direction*24;for(int i=0;i<100&&!struck.Contains(target.id);i++)ball.Advance(.02f,false);bool confirmed=struck.Contains(target.id);ball.FinishExperience();if(confirmed)return;}throw new Exception("No target-specific native collision with "+target.kind+" "+target.id);}
  try{Interests();ball.ResetWorld();
   var home=ball.transform.position;god.transform.position=home-Vector3.right*nav.world.Scale*6-Vector3.up*nav.world.Scale*ball.Radius;ball.Advance(.02f,false);int kicks=test.WorldPlay.kicks;for(int i=0;i<80&&test.WorldPlay.kicks==kicks;i++){god.transform.position+=Vector3.right*nav.world.Scale*.08f;ball.Advance(.02f,false);}if(test.WorldPlay.kicks!=kicks+1||ball.Body.linearVelocity.x<1)throw new Exception("Creature contact did not kick ball");ball.FinishExperience();if(god.State.Interest(ball.StableId).appeal<=.5f||test.WorldPlay.nextKick-god.State.time>2)throw new Exception("Controlled tap reward/cooldown incorrect");int count=test.WorldPlay.kicks;for(int i=0;i<50;i++)ball.Advance(.02f,false);if(test.WorldPlay.kicks!=count)throw new Exception("Stationary overlap rewarded");god.transform.position=godPosition;ball.ReturnHome();test.WorldPlay.nextKick=0;test.WorldPlay.throws=test.WorldPlay.safeThrows=test.WorldPlay.harmfulThrows=0;
if(Mathf.Abs(ball.transform.lossyScale.x/nav.world.Scale-7)>.01f)throw new Exception("Beachball is not large");
   foreach(var v in residents){v.ResetTask();v.GetComponent<VillagerExploration>().ResetTask();v.GetComponent<VillagerBlockPlay>().ResetTask();}
   var house=slice.GetComponentsInChildren<PlayImpactTarget>().Where(t=>t.kind=="building").OrderBy(t=>Vector3.Distance(t.transform.position,ball.transform.position)).First();var renderer=house.GetComponentsInChildren<Renderer>()[0];var beforeTint=new MaterialPropertyBlock();renderer.GetPropertyBlock(beforeTint,0);house.Apply(.5f);house.Apply(0);var afterTint=new MaterialPropertyBlock();renderer.GetPropertyBlock(afterTint,0);if(beforeTint.GetColor("_Color")!=afterTint.GetColor("_Color")||beforeTint.GetFloat("_Recolor")!=afterTint.GetFloat("_Recolor"))throw new Exception("Damage changed original material tint/recolor");var witness=residents[0];witness.transform.position=house.transform.position+Vector3.forward*nav.world.Scale*10;float trust=witness.Memory.trust;Hit(house);if(test.WorldPlay.Damage(house.id)<=0||witness.Memory.trust>=trust||witness.Current!=VillagerSocial.Phase.Recoil||test.WorldPlay.harmfulThrows!=1)throw new Exception("House impact lacked physical damage, blame or negative reaction");float damage=test.WorldPlay.Damage(house.id);ball.Impact(house,24);if(test.WorldPlay.Damage(house.id)!=damage)throw new Exception("Same throw damaged twice");Hit(house);if(test.WorldPlay.Damage(house.id)<1)throw new Exception("Repeated hard impacts did not collapse house");
   var tree=slice.GetComponentsInChildren<PlayImpactTarget>().Where(t=>t.kind=="tree").OrderBy(t=>Vector3.Distance(t.transform.position,ball.transform.position)).First();Hit(tree);if(test.WorldPlay.Damage(tree.id)<=0)throw new Exception("Tree ignored ball");
   var victim=residents[1];victim.transform.position=nav.world.Terrain.Project(house.transform.position+Vector3.forward*nav.world.Scale*24);var victimTarget=victim.GetComponent<PlayImpactTarget>();Hit(victimTarget);if(victim.Memory.injury<=0)throw new Exception("Villager collision had no injury");trust=witness.Memory.trust;Hit(house,false);if(witness.Memory.trust!=trust)throw new Exception("Player throw blamed creature");
   ball.ReturnHome();ball.Throw(Vector3.forward);var position=ball.Body.position;ball.Advance(2,true);if(ball.Body.position!=position)throw new Exception("Paused ball moved");ball.FinishExperience();int safe=test.WorldPlay.safeThrows,harm=test.WorldPlay.harmfulThrows;ball.Impact(house,24);if(test.WorldPlay.safeThrows!=safe-1||test.WorldPlay.harmfulThrows!=harm+1)throw new Exception("Late harm did not revise a safe outcome");
   ball.ResetWorld();god.Interrupt("Native throw test");var prop=ball.GetComponent<CreatureAffordance>();prop.cooldown=0;if(!nav.world.Sample(ball.transform.position,nav.profile,12,out var start))throw new Exception("No ball approach");god.transform.position=nav.world.ProjectFoot(start,nav.profile);nav.ResetRoute();int played=mind.played;if(!mind.TryBegin(prop))throw new Exception("Creature refused beachball");bool throwPhase=false;for(int i=0;i<2000&&mind.Current!=CreatureCuriosity.Phase.Rest;i++){mind.Tick(.02f,test);ball.Advance(.02f,false);throwPhase|=mind.Current==CreatureCuriosity.Phase.WatchBall;}if(!throwPhase||mind.played!=played+1||ball.GetComponent<CarryItem>().held)throw new Exception("Creature did not carry, throw, watch and release ball");
   var save=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));if(!save.Valid()||save.WorldPlay.damage.Length<3||save.WorldPlay.caution<=.2f)throw new Exception("Damage/caution did not save");
   Debug.Log("BWVR_BEACHBALL_PASS: seven-unit striped ball; native PhysX house/tree/villager contacts; collapse, injury, nearby fear and source attribution; per-throw deduplication; pause; native reach/carry/throw/watch; persistent fun/caution, damage and favorites");
  }finally{god.Interrupt("Ball QA complete");ball.FinishExperience();for(int i=0;i<residents.Length;i++){residents[i].ResetTask();residents[i].transform.position=residentPositions[i];residents[i].GetComponent<IslandNavigator>().ResetRoute();}god.transform.position=godPosition;nav.ResetRoute();field.SetValue(slice,original);ball.ResetWorld();}
 }
}
}
